// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { getHighlights, putHighlights } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const highlightsPutRequestBody: string = `{
        "color": "yellow",
        "comment": "method not allowed probe"
    }`;

    const highlightsGetResponse = await getHighlights(client, URL_localhost, headers);
    expect(highlightsGetResponse.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGetResponse, "response.highlights"), 'the accepted read returns a highlights list').not.toBeNull();

    const highlightsGet1Response = await getHighlights(client, URL_localhost, headers, {"color": ["purple"]}, 400);
    expect(highlightsGet1Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet1Response, "response"), 'unsupported colour message').toBe("Invalid color. Allowed colors are: yellow, green, blue, red.");

    const highlightsGet2Response = await getHighlights(client, URL_localhost, headers, {"color": ["Yellow"]}, 400);
    expect(highlightsGet2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet2Response, "response"), 'colour matching is case sensitive').toBe("Invalid color. Allowed colors are: yellow, green, blue, red.");

    const highlightsGet3Response = await getHighlights(client, URL_localhost, headers, {"take": ["0"]}, 400);
    expect(highlightsGet3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet3Response, "response"), 'take below the lower bound').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet4Response = await getHighlights(client, URL_localhost, headers, {"take": ["101"]}, 400);
    expect(highlightsGet4Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet4Response, "response"), 'take past the upper bound').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet5Response = await getHighlights(client, URL_localhost, headers, {"take": ["abc"]}, 400);
    expect(highlightsGet5Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet5Response, "response"), 'take that is not a number').toBe("take must be a whole number between 1 and 100.");

    const highlightsGet6Response = await getHighlights(client, URL_localhost, headers, {"cursor": ["0"]}, 400);
    expect(highlightsGet6Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet6Response, "response"), 'cursor below the lower bound').toBe("cursor must be the id of a highlight.");

    const highlightsGet7Response = await getHighlights(client, URL_localhost, headers, {"cursor": ["abc"]}, 400);
    expect(highlightsGet7Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(highlightsGet7Response, "response"), 'cursor that is not a number').toBe("cursor must be the id of a highlight.");

    const highlightsGet8Response = await getHighlights(client, URL_localhost, headers, {"take": ["1"]});
    expect(highlightsGet8Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet8Response, "response.highlights").length, 'take at the lower bound is honoured').toBeLessThanOrEqual(1);

    const highlightsGet9Response = await getHighlights(client, URL_localhost, headers, {"take": ["100"]});
    expect(highlightsGet9Response.statusCode, 'status code').toBe(200);
    expect(getResponseValue(highlightsGet9Response, "response.highlights").length, 'take at the upper bound is honoured').toBeLessThanOrEqual(100);

    const highlightsPutResponse = await putHighlights(client, URL_localhost, headers, highlightsPutRequestBody);
    expect(highlightsPutResponse.statusCode, 'status code').toBe(405);
    expect(getResponseValue(highlightsPutResponse, "response"), 'unimplemented method is answered').toBe("Method not allowed.");
});
